import{_ as e,c as t,o as i}from"./chunks/framework.BO4SuroD.js";const u=JSON.parse(`{"title":"BeThere","description":"","frontmatter":{"layout":"home","title":"BeThere","hero":{"name":"Never Build an Agent from Scratch","tagline":"With OpenCUI: A component-based platform by BeThere, bringing conversation designers and developers together to build conversational experiences that get results.","actions":[{"theme":"brand","text":"Let's Build","link":"https://build.opencui.io/","type":"primary"}]},"contentCards":[{"title":"Three-Layer Architecture for Multilingual and Multiplatform Services","details":"By separating language perception, interaction logic, and backend services, a three-layer architecture naturally delivers a consistent user experience across languages while enabling seamless transitions between web, mobile, and chat platforms.","image":"images/architecture.png","left":true},{"title":"Statechart-based Interaction Logic for Control and Flexibility","details":"Conversation flows offer precision, but enumerating all possible flows is impractical. Prompt engineering provides broad coverage but lacks control. Statechart-based interaction logic, built by annotating service schemas, achieve both through this factorized and declarative approach.","image":"images/schema.png","left":false},{"title":"Agentic Dialogue Understanding for Production Accuracy","details":"No LLM achieves 100% accuracy on standard function-calling datasets, let alone for custom use cases. By decomposing dialogue understanding into manageable subproblems, leveraging retrieval-augmented in-context learning using fine-tuned model for inference, and intelligently merging the solutions, our agentic dialogue understanding provides a cost-effective solution to achieve the accuracy required for production.","image":"images/language.png","left":true},{"title":"Open, Modular Design for Limitless Extensions.","details":"Sounds great, but how does it integrate with your existing system? With its modular design and open-architecture runtime, you can easily build extensions that connect seamlessly to your infrastructure—and beyond.","image":"images/composable.png","left":false},{"title":"Dual Process for Coverage","details":"Seamlessly switch between software-engineered System 2, offering deterministic conversational services on APIs, and prompt-engineered System 1, utilizing retrieval-augmented generation for unstructured text. Our dual-process approach consistently delivers a cost-effective conversational experience, providing control for high-impact queries and coverage for the rest.","image":"images/system1.png","left":true}],"cta":[{"details":"With copilot, you can build a table reservation agent by simply answering questions.","title":"Try it yourself","link":"https://build.opencui.io/copilot"}],"columnFooter":[{"title":"BeThere","tagline":"We build OpenCUI, so you don't have to build agents from scratch.","logo":"/images/logo.png","footerItems":[{"title":"Social","items":[{"text":"Medium","link":"https://opencui.medium.com/"},{"text":"Discord","link":"https://discord.gg/4Fqb6NtC"},{"text":"LinkedIn","link":"https://www.linkedin.com/company/10969501/"}]},{"title":"Legal","items":[{"text":"Terms of Service","link":"/policy/terms"},{"text":"Privacy policy","link":"/policy/privacy"}]}]}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1737583776000}`),n={name:"index.md"};function a(o,r,s,l,c,d){return i(),t("div")}const m=e(n,[["render",a]]);export{u as __pageData,m as default};
